using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class SpatialWalk {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var routes=JArray.Parse(File.ReadAllText(repo+"/SourceAssets/B5_SpatialRefinement/walk_plan.json"));var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();float radius=cc.radius;var start=player.transform.position;bool was=cc.enabled;var results=new List<object>();try{foreach(var route in routes){var points=route["points"].Select(p=>new Vector3((float)p[0],(float)p[1],(float)p[2])).ToArray();cc.enabled=false;player.transform.position=points[0]+Vector3.up*(cc.height*.5f-cc.center.y+.035f);cc.enabled=true;Physics.SyncTransforms();int steps=0,index=0;bool passed=true;float remaining=0;Vector3 target=points[0];foreach(var to in points.Skip(1)){index++;target=to;int limit=(int)(Vector3.Distance(player.transform.position,to)/.05f)+50;for(int i=0;i<limit;i++){var d=to-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.025f)break;cc.Move(d.normalized*Mathf.Min(.05f,remaining)+Vector3.down*.045f);steps++;}if(remaining>.08f){passed=false;break;}}for(int i=0;i<12;i++)cc.Move(Vector3.down*.035f);float bottom=player.transform.position.y+cc.center.y-cc.height*.5f;float heightError=bottom-target.y;if(Mathf.Abs(heightError)>.30f)passed=false;results.Add(new{id=(string)route["id"],passed,steps,index,remaining,heightError,foot=new[]{player.transform.position.x,bottom,player.transform.position.z},target=new[]{target.x,target.y,target.z}});}}finally{cc.enabled=false;player.transform.position=start;cc.enabled=was;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(repo+"/Docs/검수/2026-11-08_B5_SpatialRefinement/walk.json",JsonConvert.SerializeObject(new{radius,results},Formatting.Indented));return new{routes=routes.Count,results};}
}
